<?php
namespace App\Http\Controllers;use App\Http\Requests\SendTestRequest;use App\Jobs\SendTestEmailJob;use Illuminate\Http\JsonResponse;use Illuminate\Support\Facades\Log;
final class SendController {public function __invoke(SendTestRequest $request):JsonResponse{$d=$request->validated();try{SendTestEmailJob::dispatchSync($d);return response()->json(['ok'=>true,'data'=>['message'=>'Email sent successfully!']]);}catch(\Throwable $e){Log::error('V2 test email failed',['exception'=>$e::class]);$m=$e->getMessage();$message=match(true){str_contains($m,'Authentication')=>'Authentication failed. Check your sender email and password (or App Password for Gmail). Error: '.$m,str_contains($m,'Connection refused')||str_contains($m,'No route to host')=>'Could not connect to SMTP server. Check host/port or internet connection. Error: '.$m,str_contains($m,'SSL')||str_contains($m,'certificate')=>'SSL/TLS Error: Port/Encryption mismatch. Ensure you are using port 465 for SSL or 587 for STARTTLS. Error: '.$m,default=>'Failed to send email: An unexpected error occurred: '.$m};return response()->json(['ok'=>false,'error'=>['code'=>'smtp_send_failed','message'=>$message]],422);}}}
